import re

PATTERN = re.compile(r"^(?P<metric>[a-zA-Z_:][a-zA-Z0-9_:]*)(?P<labels>{[^}]*})? (?P<value>[^ ]+)(?: (?P<ts>\d+))?$")
LABEL = re.compile(r'([a-zA-Z_][a-zA-Z0-9_]*)="((?:[^"\\]|\\.)*)"')

def parse_sample(line):
    m = PATTERN.match(line.strip())
    if not m:
        return None
    labels = {}
    if m.group("labels"):
        for key, val in LABEL.findall(m.group("labels")):
            labels[key] = val.replace(chr(92) + '"', '"').replace(chr(92) + chr(92), chr(92))
    return {"metric": m.group("metric"), "labels": labels, "value": float(m.group("value"))}
